using ProMaxx2.QA.Application.Projects;using ProMaxx2.QA.Domain.Execution;
namespace ProMaxx2.QA.Application.Execution;
public sealed record EnvironmentDto(Guid TestEnvironmentId,Guid ProjectId,string EnvironmentName,string?BaseUrl,bool IsActive);public sealed record SaveEnvironmentRequest(Guid ProjectId,string EnvironmentName,string?BaseUrl,bool IsActive=true);public sealed record TestCycleDto(Guid TestCycleId,Guid ProjectId,Guid ReleaseId,string ReleaseCode,Guid BuildId,string BuildNumber,Guid EnvironmentId,string EnvironmentName,Guid?TestSuiteId,string?SuiteName,string CycleCode,string CycleName,string?CycleType,DateTime?StartDate,DateTime?EndDate,Guid?OwnerUserId,string Status,string?Notes,int CaseCount,int ExecutedCount,decimal ProgressPercent);public sealed record SaveTestCycleRequest(Guid ProjectId,Guid ReleaseId,Guid BuildId,Guid EnvironmentId,Guid?TestSuiteId,string CycleCode,string CycleName,string?CycleType,DateTime?StartDate,DateTime?EndDate,Guid?OwnerUserId,string?Notes,bool PopulateFromSuite=true,bool RequiredOnly=false);public sealed record ChangeCycleStatusRequest(string Status);
public interface ITestCycleRepository{Task<IReadOnlyList<EnvironmentDto>>EnvironmentsAsync(Guid?projectId,CancellationToken ct);Task AddEnvironmentAsync(TestEnvironment entity,CancellationToken ct);Task<IReadOnlyList<TestCycleDto>>ListAsync(Guid?projectId,CancellationToken ct);Task<TestCycleDto?>GetAsync(Guid id,CancellationToken ct);Task<TestCycle?>FindAsync(Guid id,CancellationToken ct);Task<bool>CodeExistsAsync(Guid projectId,string code,CancellationToken ct);Task ValidateReferencesAsync(SaveTestCycleRequest r,CancellationToken ct);Task AddAsync(TestCycle entity,CancellationToken ct);Task PopulateAsync(Guid cycleId,Guid suiteId,bool requiredOnly,CancellationToken ct);Task SaveAsync(CancellationToken ct);}
public sealed class TestCycleService(ITestCycleRepository repository){public Task<IReadOnlyList<EnvironmentDto>>EnvironmentsAsync(Guid?p,CancellationToken ct)=>repository.EnvironmentsAsync(p,ct);public async Task<EnvironmentDto>CreateEnvironmentAsync(SaveEnvironmentRequest r,CancellationToken ct){var e=new TestEnvironment(r.ProjectId,r.EnvironmentName,r.BaseUrl);await repository.AddEnvironmentAsync(e,ct);await repository.SaveAsync(ct);return(await repository.EnvironmentsAsync(r.ProjectId,ct)).Single(x=>x.TestEnvironmentId==e.TestEnvironmentId);}public Task<IReadOnlyList<TestCycleDto>>ListAsync(Guid?p,CancellationToken ct)=>repository.ListAsync(p,ct);public async Task<TestCycleDto>CreateAsync(SaveTestCycleRequest r,Guid?userId,CancellationToken ct){if(await repository.CodeExistsAsync(r.ProjectId,r.CycleCode.Trim().ToUpperInvariant(),ct))throw new DuplicateCodeException("Cycle code already exists.");await repository.ValidateReferencesAsync(r,ct);var e=new TestCycle(r.ProjectId,r.ReleaseId,r.BuildId,r.EnvironmentId,r.TestSuiteId,r.CycleCode,r.CycleName,r.CycleType,r.StartDate,r.EndDate,r.OwnerUserId,r.Notes,userId);await repository.AddAsync(e,ct);await repository.SaveAsync(ct);if(r.PopulateFromSuite&&r.TestSuiteId.HasValue){await repository.PopulateAsync(e.TestCycleId,r.TestSuiteId.Value,r.RequiredOnly,ct);await repository.SaveAsync(ct);}return(await repository.GetAsync(e.TestCycleId,ct))!;}public async Task<TestCycleDto>UpdateAsync(Guid id,SaveTestCycleRequest r,CancellationToken ct){var e=await repository.FindAsync(id,ct)??throw new EntityNotFoundException("Test cycle not found.");e.Update(r.CycleName,r.CycleType,r.StartDate,r.EndDate,r.OwnerUserId,r.Notes);await repository.SaveAsync(ct);return(await repository.GetAsync(id,ct))!;}public async Task<TestCycleDto>StatusAsync(Guid id,string status,CancellationToken ct){var e=await repository.FindAsync(id,ct)??throw new EntityNotFoundException("Test cycle not found.");e.ChangeStatus(status);await repository.SaveAsync(ct);return(await repository.GetAsync(id,ct))!;}}
